"""Checked-in presentation classification for canonical MCP tool names.

The inventory is representation metadata only. It never registers a handler or
changes FastMCP listing, invocation, approval, module-state, or caller authority.
"""

from __future__ import annotations

from types import MappingProxyType

from butlers.core.tool_catalog import (
    OwnerNotifyBranch,
    RecipientParameters,
    StoreWriters,
    ToolPresentation,
)


def _declare(
    module: str,
    group: str,
    names: str,
    *,
    presentable: bool = True,
    posture: str = "deferred",
    namespace: str | None = None,
    **authorization: object,
) -> tuple[ToolPresentation, ...]:
    # Provider/cache responses retain their external provenance even on writes.
    external_modules = {
        "google_drive",
        "calendar",
        "email",
        "telegram",
        "whatsapp",
        "home_assistant",
        "spotify",
        "steam",
        "google_health",
    }
    if module in external_modules:
        boundary = f"external:{module}"
        authorization["read_stores"] = (*authorization.get("read_stores", ()), boundary)
        if authorization.get("effect_class") != "read":
            authorization["write_stores"] = (*authorization.get("write_stores", ()), boundary)
    return tuple(
        ToolPresentation(
            canonical_name=name,
            module_name=module,
            group_name=group,
            namespace=f"{module}.{namespace or group}",
            llm_presentable=presentable,
            load_posture=posture,  # type: ignore[arg-type]
            **authorization,
        )
        for name in names.split()
    )


